+  virtual int HandleCommand(HTIFCOMMAND cmd) override;
+
+protected:
+  int exit(uint64_t a0, uint64_t a1, uint64_t a2, uint64_t a3, uint64_t a4, uint64_t a5, uint64_t a6);
+
+  std::vector<SYSCALLHANDLER> m_cmdHandlers;
+};
