+int InstructionSetSimulator::OnKill(uint64_t uiProcId)
+{
+  // reload the elf
+  udb::ElfReader elfReader(m_opts.elfFilePath.c_str());
+  auto entryPC = elfReader.loadLoadableSegments(*m_pSoC);
+  // reset the hart
+  m_pHart->reset(entryPC);
+  // set the ISS state
+  SetInitState(m_opts);
+  return 0;
+}
