+udb::Tracer* InstructionSetSimulator::CreateTracer(std::string& tracer)
+{
+  if(tracer == "inst")
+    return new udb::InstructionTracer(m_pHart);
+  else if(tracer == "mem")
+    return new udb::MemoryTracer(m_pSoC);
+
+  return nullptr;
+}
